def function_part(k):
    if k == 0:
        return pf.Scalar.zero()
    fun = b4_function()
    points = [ctx[f"x_{j}"] for j in range(N_int)] + [ctx[f"y_{N_int}"]]
    f_star = fun(ctx["x_star"])
    value = sum((sample_star_weights[j] * (fun(points[j]) - f_star)
                 for j in range(k + 1)), pf.Scalar.zero())
    value += sum((sample_chain_weights[j] * (fun(points[j + 1]) - fun(points[j]))
                  for j in range(k)), pf.Scalar.zero())
    return value

def V_k_structure(k):
    vectors = V_k_basis(k)
    C = np.asarray(coeff_by_k[k], dtype=float).reshape(len(vectors), len(vectors))
    assert C.shape == (len(vectors), len(vectors))
    quadratic = sum((float(C[i,j]) * vectors[i] * vectors[j]
                     for i, j in np.ndindex(C.shape)), pf.Scalar.zero())
    # Every cumulative function term is retained, including small balance errors.
    # The interpolation-only prefixes have identically zero scalar offset.
    return quadratic + function_part(k)

